<?php
require_once 'functions.php';
$q = trim($_GET['q'] ?? ''); $type = $_GET['type'] ?? ''; $category = $_GET['category'] ?? '';
$sql = "SELECT i.*, u.full_name FROM items i JOIN users u ON u.id=i.user_id WHERE i.status='active'"; $params=[];
if ($q !== '') { $sql .= " AND (i.title LIKE ? OR i.place LIKE ? OR i.description LIKE ?)"; $like="%$q%"; array_push($params,$like,$like,$like); }
if (in_array($type,['lost','found'],true)) { $sql .= " AND i.item_type=?"; $params[]=$type; }
if ($category !== '') { $sql .= " AND i.category=?"; $params[]=$category; }
$sql .= ' ORDER BY i.created_at DESC'; $stmt=$pdo->prepare($sql); $stmt->execute($params); $items=$stmt->fetchAll();
$categories=$pdo->query('SELECT DISTINCT category FROM items ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);
$stats=$pdo->query("SELECT COUNT(*) total, SUM(item_type='lost' AND status='active') lost_count, SUM(item_type='found' AND status='active') found_count, SUM(status='returned') returned_count FROM items")->fetch();
page_header('Browse items'); ?>
<section class="hero"><div><p class="eyebrow">COMMUNITY LOST &amp; FOUND</p><h1>Lost something?<br><span>Let’s find it.</span></h1><p class="hero-copy">Search reports from your community or share an item you found.</p><div class="hero-actions"><a class="button" href="report.php">＋ Report an item</a><a class="button secondary" href="#listings">Browse listings</a></div></div><div class="hero-art"><div class="art-circle">⌕</div><div class="art-note">A little help can<br>make someone’s day.</div></div></section>
<section class="stats"><div><strong><?= (int)$stats['total'] ?></strong><span>Total reports</span></div><div><strong><?= (int)$stats['lost_count'] ?></strong><span>Lost items</span></div><div><strong><?= (int)$stats['found_count'] ?></strong><span>Found items</span></div><div><strong><?= (int)$stats['returned_count'] ?></strong><span>Returned</span></div></section>
<section id="listings" class="section-head"><div><p class="eyebrow">COMMUNITY BOARD</p><h2>Recent listings</h2></div><span class="muted"><?=count($items)?> result(s)</span></section>
<form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search item, location, details…"><select name="type"><option value="">All reports</option><option value="lost" <?=$type==='lost'?'selected':''?>>Lost</option><option value="found" <?=$type==='found'?'selected':''?>>Found</option></select><select name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach; ?></select><button class="button" type="submit">Search</button><a class="reset" href="index.php">Reset</a></form>
<div class="item-grid"><?php if(!$items): ?><div class="empty">No listings found. Try a different search or report an item.</div><?php endif; ?><?php foreach($items as $item): ?><article class="item-card"><?php if($item['photo_path']): ?><img class="item-photo" src="<?=e($item['photo_path'])?>" alt="Item photo"><?php else: ?><div class="item-placeholder"><?= $item['item_type']==='lost'?'⌕':'✦' ?></div><?php endif; ?><div class="card-content"><div class="card-top"><span class="pill <?=$item['item_type']?>"><?=e(ucfirst($item['item_type']))?></span><span class="muted small"><?=e($item['category'])?></span></div><h3><?=e($item['title'])?></h3><p class="item-location">⌖ <?=e($item['place'])?></p><p class="muted small">Date: <?=e($item['item_date'])?></p><p class="description"><?=e(mb_strimwidth($item['description'] ?? '',0,115,'…'))?></p><a class="text-link" href="item.php?id=<?=(int)$item['id']?>">View details →</a></div></article><?php endforeach; ?></div>
<?php page_footer(); ?>
